import unittest

def remove_adjacent_duplicates(lst):
    if not lst:
        return []

    result = [lst[0]]
    for item in lst[1:]:
        if item != result[-1]:
            result.append(item)

    return result

class TestRemoveAdjacentDuplicates(unittest.TestCase):
